INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'matthew' AND c.chapter_number = 5 AND v.verse_number = 5), 'kingdom', 'The kingdom', 'The meek shall inherit the earth — a land promise, quoted', $card$*Blessed are the meek: for they shall inherit the earth.* (Matthew 5:5)

*But the meek shall inherit the earth; and shall delight themselves in the abundance of peace.* (Psalm 37:11)

*The righteous shall inherit the land, and dwell therein for ever.* (Psalm 37:29)

The beatitude is Psalm 37, nearly word for word — and Psalm 37 is a land psalm. The meek inherit the land and dwell therein for ever, while the wicked are cut off from it. The inherited reading hears a gentle sentiment and looks away toward heaven. The psalm being quoted looks toward the earth — the inheritance the kingdom restores to the meek who wait on Yahuah (God).$card$, '{"Psalm 37:11","Psalm 37:29","Matthew 5:5"}'::TEXT[], 'free', NOW())
