VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'psalms' AND c.chapter_number = 37 AND v.verse_number = 29), 'kingdom', 'The kingdom', 'The meek shall inherit the earth — a land promise, quoted', $card$*Blessed are the meek: for they shall inherit the earth.* (Matthew 5:5)

