INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'matthew' AND c.chapter_number = 10 AND v.verse_number = 6), 'gathering', 'The gathering', 'Go rather to the lost sheep — the prophets filed the missing-persons report', $card$*These twelve Yahusha (Jesus) sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not: But go rather to the lost sheep of the house of Yashar'el (Israel).* (Matthew 10:5-6)

*My people hath been lost sheep: their shepherds have caused them to go astray, they have turned them away on the mountains: they have gone from mountain to hill, they have forgotten their restingplace.* (Jeremiah 50:6)

*My sheep wandered through all the mountains, and upon every high hill: yea, my flock was scattered upon all the face of the earth, and none did search or seek after them.* (Ezekiel 34:6)

*Lost sheep* is not a figure of speech invented for the sending. It is a case the prophets had already opened: *my people hath been lost sheep,* scattered upon all the face of the earth, *and none did search or seek after them.* The twelve are sent as the search party Ezekiel said was missing — and the mission's address, the house of Yashar'el (Israel), is the flock's name on the report.$card$, '{"Jeremiah 50:6","Ezekiel 34:6","Matthew 10:5-6"}'::TEXT[], 'free', NOW())
