INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'matthew' AND c.chapter_number = 11 AND v.verse_number = 28), 'grace', 'Grace', 'Rest for your souls — found in the old paths', $card$*Come unto me, all ye that labour and are heavy laden, and I will give you rest. Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light.* (Matthew 11:28-30)

*Thus saith Yahuah (LORD), Stand ye in the ways, and see, and ask for the old paths, where is the good way, and walk therein, and ye shall find rest for your souls. But they said, We will not walk therein.* (Jeremiah 6:16)

*Ye shall find rest unto your souls* is Jeremiah's sentence, and in Jeremiah the rest has one location: the old paths, the good way — *walk therein.* The inherited reading sets the easy yoke against the commandments, as if rest were the alternative to the way. The verse being quoted says the opposite. The rest is what the good way feels like when the one who gives it carries the burden home. Grace does not retire the old paths; it returns the weary traveler onto them.$card$, '{"Jeremiah 6:16","Matthew 11:28-30"}'::TEXT[], 'free', NOW())
