INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'matthew' AND c.chapter_number = 13 AND v.verse_number = 43), 'kingdom', 'The kingdom', 'The righteous shall shine as the sun — Daniel saw the brightness first', $card$*Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear.* (Matthew 13:43)

*And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.* (Daniel 12:3)

The explanation of the wheat and the tares ends on a sentence from Daniel — the wise shining as the brightness of the firmament at the time of the end. The harvest, the separating, the shining: the parable closes its teaching by landing on the prophecy it was unfolding the whole time. *Who hath ears to hear* — the hearer with Daniel in his ears had already heard it.$card$, '{"Daniel 12:3","Matthew 13:43"}'::TEXT[], 'free', NOW())
