INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'matthew' AND c.chapter_number = 18 AND v.verse_number = 11), 'good_news', 'The good news', 'Come to save that which was lost — spoken first in the first person', $card$*For the Son of Adam is come to save that which was lost.* (Matthew 18:11)

*I will seek that which was lost, and bring again that which was driven away, and will bind up that which was broken, and will strengthen that which was sick: but I will destroy the fat and the strong; I will feed them with judgment.* (Ezekiel 34:16)

No *as it is written* introduces it, but the sentence was already written. *I will seek that which was lost* is the promise of Ezekiel's shepherd chapter — the recovery of the scattered flock, the broken bound up, the driven-away brought again. When the Son of Adam names his errand, he names it in the promise's own words. The good news is not a new rescue invented in Galilee; it is the old rescue arriving.$card$, '{"Ezekiel 34:16","Matthew 18:11"}'::TEXT[], 'free', NOW())
