VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'ezekiel' AND c.chapter_number = 34 AND v.verse_number = 16), 'good_news', 'The good news', 'Come to save that which was lost — spoken first in the first person', $card$*For the Son of Adam is come to save that which was lost.* (Matthew 18:11)

