INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'mark' AND c.chapter_number = 4 AND v.verse_number = 29), 'kingdom', 'The kingdom', 'He putteth in the sickle — Joel''s harvest', $card$*And he said, So is the kingdom of Elohim (God), as if a man should cast seed into the ground; And should sleep, and rise night and day, and the seed should spring and grow up, he knoweth not how. For the earth bringeth forth fruit of herself; first the blade, then the ear, after that the full corn in the ear. But when the fruit is brought forth, immediately he putteth in the sickle, because the harvest is come.* (Mark 4:26-29)

*Put ye in the sickle, for the harvest is ripe: come, get you down; for the press is full, the fats overflow; for their wickedness is great.* (Joel 3:13)

The parable's last line is Joel's, almost verbatim: *put ye in the sickle, for the harvest is ripe.* In Joel the sickle marks the day of Yahuah (God) — the gathering to judgment when the wickedness is full. The kingdom of Elohim (God) grows quietly, blade and ear and full corn, the sower sleeping and rising — but it grows toward Joel's day. The parable does not soften the harvest. It teaches the patience that precedes it.$card$, '{"Joel 3:13","Mark 4:26-29"}'::TEXT[], 'free', NOW())
