    last_reviewed_at = NOW(),
    updated_at = NOW();

INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'luke' AND c.chapter_number = 22 AND v.verse_number = 30), 'kingdom', 'The kingdom', 'Thrones judging the twelve tribes of Yashar''el (Israel)', $card$*Ye are they which have continued with me in my temptations. And I appoint unto you a kingdom, as my Father hath appointed unto me; That ye may eat and drink at my table in my kingdom, and sit on thrones judging the twelve tribes of Yashar'el (Israel).* (Luke 22:28-30)

*Whither the tribes go up, the tribes of Yahuah (LORD), unto the testimony of Yashar'el (Israel), to give thanks unto the name of Yahuah (LORD). For there are set thrones of judgment, the thrones of the house of David.* (Psalm 122:4-5)

On the night the covenant was cut, he appointed a kingdom — and described it in furniture: a table, and thrones judging the twelve tribes of Yashar'el (Israel). David's city already held that furniture in song: *there are set thrones of judgment, the thrones of the house of David,* in the place whither the tribes go up.

Twelve thrones for twelve tribes, set in the house of David. The kingdom he appointed at the table is the one the psalm had been singing all along — nothing in it transferred to another people, nothing in it dissolved into metaphor. The tribes go up; the thrones are set; the appointment stands.$card$, '{"Psalm 122:4-5","Luke 22:28-30"}'::TEXT[], 'free', NOW())
