VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'psalms' AND c.chapter_number = 122 AND v.verse_number = 5), 'kingdom', 'The kingdom', 'Thrones judging the twelve tribes of Yashar''el (Israel)', $card$*Ye are they which have continued with me in my temptations. And I appoint unto you a kingdom, as my Father hath appointed unto me; That ye may eat and drink at my table in my kingdom, and sit on thrones judging the twelve tribes of Yashar'el (Israel).* (Luke 22:28-30)

