    anchor_refs = EXCLUDED.anchor_refs,
    last_reviewed_at = NOW(),
    updated_at = NOW();

INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'isaiah' AND c.chapter_number = 55 AND v.verse_number = 7), 'teaching', 'The teaching', 'Thus it is written... among all nations', $card$*And said unto them, Thus it is written, and thus it behoved Messiah (Christ) to suffer, and to rise from the dead the third day: And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem.* (Luke 24:46-47)

*Let the wicked forsake his way, and the unrighteous man his thoughts: and let him return unto Yahuah (LORD), and he will have mercy upon him; and to our Elohim (God), for he will abundantly pardon.* (Isaiah 55:7)

*O Yahuah (LORD), my strength, and my fortress, and my refuge in the day of affliction, the Gentiles shall come unto thee from the ends of the earth, and shall say, Surely our fathers have inherited lies, vanity, and things wherein there is no profit.* (Jeremiah 16:19)

*Thus it is written* — including the part the inherited reading treats as new: repentance and remission preached among all nations. Isaiah wrote the repentance: let him *return* unto Yahuah (God), and he will abundantly pardon. Repentance in the prophets' tongue is return.

And Jeremiah heard what the preaching among all nations produces: they *shall come unto thee from the ends of the earth, and shall say, Surely our fathers have inherited lies.* The preaching goes out into every nation because the scattered seed lives in every nation, and the sheep hear. The confession of inherited lies is the sound of the return beginning.$card$, '{"Isaiah 55:7","Jeremiah 16:19","Luke 24:46-47"}'::TEXT[], 'free', NOW())
