VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'hosea' AND c.chapter_number = 1 AND v.verse_number = 11), 'gathering', 'The gathering', 'Unto which promise our twelve tribes hope to come', $card$*And now I stand and am judged for the hope of the promise made of Elohim (God) unto our fathers: Unto which promise our twelve tribes, instantly serving Elohim (God) day and night, hope to come. For which hope’s sake, king Agrippa, I am accused of the Yahudim (Jews).* (Acts 26:6-7)

