VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'ezekiel' AND c.chapter_number = 48 AND v.verse_number = 31), 'gathering', 'The gathering', 'Twelve gates, twelve tribes — every door into the city is tribal', $card$*And had a wall great and high, and had twelve gates, and at the gates twelve angels, and names written thereon, which are the names of the twelve tribes of the children of Yashar'el (Israel):* (Revelation 21:12)

*And the gates of the city shall be after the names of the tribes of Yashar'el (Israel): three gates northward; one gate of Reuben, one gate of Yahudah (Judah), one gate of Levi.* (Ezekiel 48:31)

