VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'ezekiel' AND c.chapter_number = 36 AND v.verse_number = 24), 'grace', 'Grace', 'The Spirit causes the walking — Ezekiel''s sentence inside Paul''s', $card$*For what the law could not do, in that it was weak through the flesh, Elohim (God) sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh: That the righteousness of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit.* (Romans 8:3-4)

