INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'ephesians' AND c.chapter_number = 2 AND v.verse_number = 13), 'gathering', 'The gathering', 'Far off, made nigh — the dispersion''s own address', $card$*That at that time ye were without Messiah (Christ), being aliens from the commonwealth of Yashar'el (Israel), and strangers from the covenants of promise, having no hope, and without Elohim (God) in the world: But now in HaMashiach Yahusha (Christ Jesus) ye who sometimes were far off are made nigh by the blood of Messiah (Christ).* (Ephesians 2:12-13)

*And came and preached peace to you which were afar off, and to them that were nigh.* (Ephesians 2:17)

*O Yahuah (Lord), righteousness belongeth unto thee, but unto us confusion of faces, as at this day; to the men of Yahudah (Judah), and to the inhabitants of Jerusalem, and unto all Yashar'el (Israel), that are near, and that are far off, through all the countries whither thou hast driven them, because of their trespass that they have trespassed against thee.* (Daniel 9:7)

*I create the fruit of the lips; Peace, peace to him that is far off, and to him that is near, saith Yahuah (LORD); and I will heal him.* (Isaiah 57:19)

Far off is not a poetic distance; it is the dispersion's technical address in the prophets. Daniel confesses it for all Yashar'el (Israel) — near, and far off, through all the countries whither thou hast driven them. Isaiah promises peace to both halves of that driven people, the far off and the near. The strangers of Ephesians 2 are strangers from the covenants of promise, aliens from the commonwealth of Yashar'el (Israel) — and what they were alienated from is exactly what the blood brings them nigh to. The return is to the commonwealth, not to a substitute for it.$card$, '{"Daniel 9:7","Isaiah 57:19","Ephesians 2:12-13","Ephesians 2:17"}'::TEXT[], 'free', NOW())
ON CONFLICT (verse_id) DO UPDATE SET
    strand = EXCLUDED.strand,
    strand_label = EXCLUDED.strand_label,
    card_title = EXCLUDED.card_title,
    card_md = EXCLUDED.card_md,
