    last_reviewed_at = NOW(),
    updated_at = NOW();

INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = '1-thessalonians' AND c.chapter_number = 4 AND v.verse_number = 16), 'gathering', 'The gathering', 'The trump of Elohim (God) — in the prophets, the trumpet gathers', $card$*For Yahuah (Lord) himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of Elohim (God): and the dead in Messiah (Christ) shall rise first: Then we which are alive and remain shall be caught up together with them in the clouds, to meet Yahuah (Lord) in the air: and so shall we ever be with Yahuah (Lord).* (1 Thessalonians 4:16-17)

*Now we beseech you, brethren, by the coming of our Lord Yahusha HaMashiach (Lord Jesus Christ), and by our gathering together unto him,* (2 Thessalonians 2:1)

*And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship Yahuah (LORD) in the holy mount at Jerusalem.* (Isaiah 27:13)

*And he shall set up an ensign for the nations, and shall assemble the outcasts of Yashar'el (Israel), and gather together the dispersed of Yahudah (Judah) from the four corners of the earth.* (Isaiah 11:12)

Paul names the event himself in the next letter: our gathering together unto him. And in the prophets the great trumpet has one work — it gathers. At its blast the ones ready to perish in Assyria and the outcasts in Egypt come home to worship; the ensign assembles the outcasts of Yashar'el (Israel) and the dispersed of Yahudah (Judah) from the four corners of the earth. The catching up is not an escape from the story. It is the story — the gathering the prophets promised, signaled the way they said it would be signaled.$card$, '{"Isaiah 27:13","Isaiah 11:12","1 Thessalonians 4:16-17","2 Thessalonians 2:1"}'::TEXT[], 'free', NOW())
