INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'deuteronomy' AND c.chapter_number = 14 AND v.verse_number = 2), 'good_news', 'The good news', 'Redeem us from all iniquity — Psalm 130, word for word', $card$*Who gave himself for us, that he might redeem us from all iniquity, and purify unto himself a peculiar people, zealous of good works.* (Titus 2:14)

*Let Yashar'el (Israel) hope in Yahuah (LORD): for with Yahuah (LORD) there is mercy, and with him is plenteous redemption. And he shall redeem Yashar'el (Israel) from all his iniquities.* (Psalm 130:7-8)

*For thou art an holy people unto Yahuah Elohayka (the LORD thy God), and Yahuah (LORD) hath chosen thee to be a peculiar people unto himself, above all the nations that are upon the earth.* (Deuteronomy 14:2)

Titus 2:14 is two Tanakh sentences welded together. He shall redeem Yashar'el (Israel) from all his iniquities is the psalm; a peculiar people is Deuteronomy's covenant name for the people Yahuah (God) chose unto himself. The inherited reading hears a generic church in this verse. The words themselves carry the redemption of Yashar'el (Israel) and the covenant people restored to their own name.$card$, '{"Psalm 130:7-8","Deuteronomy 14:2","Titus 2:14"}'::TEXT[], 'free', NOW())
