INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'james' AND c.chapter_number = 1 AND v.verse_number = 1), 'gathering', 'The gathering', 'To the twelve tribes which are scattered abroad — the letter''s address label', $card$*James, a servant of Elohim (God) and of the Lord Yahusha HaMashiach (Lord Jesus Christ), to the twelve tribes which are scattered abroad, greeting.* (James 1:1)

*And Yahuah (LORD) shall scatter thee among all people, from the one end of the earth even unto the other; and there thou shalt serve other gods, which neither thou nor thy fathers have known, even wood and stone.* (Deuteronomy 28:64)

*Yashar'el (Israel) is swallowed up: now shall they be among the Gentiles as a vessel wherein is no pleasure.* (Hosea 8:8)

The first line of the letter is the gathering's address label, and the inherited reading reads past it. James writes to the twelve tribes which are scattered abroad — not to a church, not to the nations at large, but to the people Moses said would be scattered among all people from the one end of the earth even unto the other, the house Hosea watched swallowed up among the Gentiles. The letter knows exactly where its readers are, and why they are there.$card$, '{"Deuteronomy 28:64","Hosea 8:8","James 1:1"}'::TEXT[], 'free', NOW())
