DO $verify$
DECLARE
    n INT;
BEGIN
    SELECT COUNT(*) INTO n FROM kingdom_verses;
    IF n < 233 THEN
        RAISE EXCEPTION 'session205 seed verify failed: % rows (expected >= 233)', n;
